<?php declare(strict_types=1);namespace FMonitor2\Otiz;use yii\db\Connection;
final class OtizSettlementV2Admission
{
 public function __construct(private Connection$db,private string$prefix){}
 public function record(int$actor,string$operationId,string$incidentId,int$objectId,string$sourceRevision,string$decision,?string$reasonCode,array$evidence,string$observedAt):array
 {
  if($actor<1||$operationId===''||$incidentId===''||$objectId<1||$sourceRevision===''||!in_array($decision,['allow','blocked','unknown'],true)||($decision==='blocked'&&trim((string)$reasonCode)==='')||array_keys($evidence)!==['acceptedOriginalId','applicationId','effectiveAttributionRevision'])throw new \InvalidArgumentException('ADMISSION_INPUT_INVALID');$json=json_encode($evidence,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$tx=$this->db->beginTransaction();try{$this->db->createCommand("INSERT IGNORE INTO `{$this->prefix}fm2_otiz_settlement_locks`(object_id)VALUES(:o)",[':o'=>$objectId])->execute();$this->db->createCommand("SELECT object_id FROM `{$this->prefix}fm2_otiz_settlement_locks` WHERE object_id=:o FOR UPDATE",[':o'=>$objectId])->queryScalar();$application=$this->db->createCommand("SELECT application_id,object_id,original_revision_id,composition_sha256 FROM `{$this->prefix}fm2_assignment_order_applications` WHERE application_id=:id AND object_id=:o FOR UPDATE",[':id'=>(int)$evidence['applicationId'],':o'=>$objectId])->queryOne();if($application===false||(string)$application['original_revision_id']!==(string)$evidence['acceptedOriginalId']||(string)$application['composition_sha256']!==(string)$evidence['effectiveAttributionRevision'])throw new \DomainException('ADMISSION_EVIDENCE_INVALID');$existing=$this->db->createCommand("SELECT object_id,source_revision,incident_id,decision,reason_code,evidence_json FROM `{$this->prefix}fm2_otiz_admission_inputs` WHERE operation_id=:op FOR UPDATE",[':op'=>$operationId])->queryOne();$expected=['object_id'=>$objectId,'source_revision'=>$sourceRevision,'incident_id'=>$incidentId,'decision'=>$decision,'reason_code'=>$reasonCode,'evidence_json'=>$json];if($existing!==false){if($existing!=$expected)throw new \DomainException('OPERATION_CONFLICT');$tx->commit();return['status'=>'no_change','objectId'=>$objectId,'sourceRevision'=>$sourceRevision,'incidentId'=>$incidentId];}$this->db->createCommand("INSERT INTO `{$this->prefix}f